Loops:
// Classic for loop
for (int i = 0; i < 5; i++) {
    System.out.print(i + " "); // 0 1 2 3 4
}

// Enhanced for-each
int[] numbers = {1, 2, 3};
for (int n : numbers) {
    System.out.print(n + " "); // 1 2 3
}

// While loop
int count = 0;
while (count < 3) {
    System.out.print(count++ + " "); // 0 1 2
}

// Do-while (runs at least once)
int x = 0;
do {
    System.out.print(x++ + " ");
} while (x < 3);

