Exception Handling:
// Try-catch-finally
try {
    int result = 10 / 0; // ArithmeticException
} catch (ArithmeticException e) {
    System.out.println("Cannot divide by zero: " + e.getMessage());
} finally {
    System.out.println("Always executes");
}

// Try-with-resources (auto-close)
try (java.io.BufferedReader br =
        new java.io.BufferedReader(new java.io.FileReader("file.txt"))) {
    String line = br.readLine();
} catch (java.io.IOException e) {
    System.err.println("IO error: " + e);
} // br.close() called automatically

// Multi-catch (Java 7+)
try {
    int[] arr = new int[3];
    arr[10] = 5;
} catch (ArrayIndexOutOfBoundsException | NullPointerException e) {
    System.err.println("Array error: " + e);
}

// Custom exception
class ValidationException extends RuntimeException {
    public ValidationException(String msg) { super(msg); }
}

var Keyword (Local Variable Type Inferen:
// Basic usage — type inferred from initializer
var message = "Hello, Java 10!"; // String
var count = 42;                     // int
var pi = 3.14159;                   // double
var list = new ArrayList<String>(); // ArrayList<String>

// Cannot use var without initializer
// var x; // compile error

// Cannot use var for fields
// class Foo { var name = "bar"; } // compile error

// Cannot use var for method parameters
// void process(var input) { } // compile error

// Cannot use var for return types
// public var getValue() { return 42; } // compile error

// Good use: diamond operator with generics
var map = new HashMap<String, List<Integer>>();
map.put("key", List.of(1, 2, 3));

// For-each with var
for (var entry : map.entrySet()) {
    System.out.println(entry.getKey() + "=" + entry.getValue());
}

// Stream pipelines — reduces noise
var result = list.stream()
    .filter(s -> s.length() > 3)
    .collect(java.util.stream.Collectors.toList());

// Avoid when type isn't obvious
// var data = fetchData(); // unclear: what does fetchData return?

Autoboxing & Unboxing:
// Autoboxing — int to Integer automatically
Integer boxed = 42; // autoboxing: int 42 to Integer.valueOf(42)

// Unboxing — Integer to int automatically
int unboxed = boxed; // unboxing: Integer to intValue()

// Collections use autoboxing
List<Integer> numbers = new ArrayList<>();
numbers.add(10); // autoboxing
int first = numbers.get(0); // unboxing

// Method arguments
public static void printDouble(Double d) {
    System.out.println(d);
}
printDouble(3.14); // autoboxing: double to Double

// Caching — values between -128 and 127 are cached
Integer a = 127;
Integer b = 127;
System.out.println(a == b); // true (both from cache)

Integer c = 128;
Integer d = 128;
System.out.println(c == d); // false (different objects!)
System.out.println(c.equals(d)); // true (compare values)

// Null danger — unboxing null throws NPE
Integer nullable = null;
// int val = nullable; // NullPointerException

// Performance: boxing in loops creates garbage
int sum = 0;
for (int i = 0; i < 10_000_000; i++) {
    sum += Integer.valueOf(i); // unboxing each iteration
}

// Wrapper in switch — autoboxing
Integer status = 200;
switch (status) {
    case 200 -> System.out.println("OK");
    case 404 -> System.out.println("Not Found");
    default -> System.out.println("Other");
}

instanceof Pattern Matching (Java 16+):
// Before Java 16 — separate type check and cast
if (obj instanceof String) {
    String s = (String) obj;
    System.out.println(s.toUpperCase());
}

// Java 16+ — pattern matching
if (obj instanceof String s) {
    // s is already a String variable in scope
    System.out.println(s.toUpperCase());
}

// With logical operators
if (obj instanceof String s && s.length() > 5) {
    System.out.println("Long string: " + s);
}

// NOT possible with || — s might not be defined
// if (obj instanceof String s || s.length() > 0) { } // compile error

// Pattern matching with nested records (Java 21+)
record Point(int x, int y) {}
if (obj instanceof Point(int x, int y)) {
    System.out.println("Point at (" + x + ", " + y + ")");
}

// Guarded patterns
if (obj instanceof String s && s.equalsIgnoreCase("hello")) {
    System.out.println("Got hello!");
}

Bitwise Operators:
int a = 0b1100; // 12 in binary
int b = 0b1010; // 10 in binary

// Bitwise AND — both bits must be 1
System.out.println(a & b); // 0b1000 = 8

// Bitwise OR — at least one bit is 1
System.out.println(a | b); // 0b1110 = 14

// Bitwise XOR — bits differ
System.out.println(a ^ b); // 0b0110 = 6

// Bitwise NOT — inverts all bits
System.out.println(~a);    // bitwise complement

// Left shift — multiplies by 2^n
System.out.println(a << 1); // 24 (12 * 2)
System.out.println(a << 2); // 48 (12 * 4)

// Right shift (signed) — divides by 2^n, preserves sign
System.out.println(a >> 1); // 6 (12 / 2)
int negative = -16;
System.out.println(negative >> 2); // -4 (preserves negative)

// Unsigned right shift — always fills with 0
System.out.println(negative >>> 2); // large positive (1073741820)

// Common use: flags and permissions
int READ = 1 << 0;   // 001
int WRITE = 1 << 1;  // 010
int EXEC = 1 << 2;   // 100

int permissions = READ | WRITE; // 011
System.out.println((permissions & READ) != 0);  // true
System.out.println((permissions & EXEC) != 0);  // false

// Check if integer is odd (LSB = 1)
System.out.println((5 & 1) == 1); // true (odd)
System.out.println((4 & 1) == 1); // false (even)

