Switch Expressions (Java 14+):
// Traditional switch statement — prone to fall-through bugs
String dayType;
switch (day) {
    case MONDAY:
    case TUESDAY:
    case WEDNESDAY:
    case THURSDAY:
    case FRIDAY:
        dayType = "Weekday";
        break;
    case SATURDAY:
    case SUNDAY:
        dayType = "Weekend";
        break;
    default:
        dayType = "Unknown";
}

// Switch expression with arrow syntax
String dayType2 = switch (day) {
    case MONDAY, TUESDAY, WEDNESDAY, THURSDAY, FRIDAY -> "Weekday";
    case SATURDAY, SUNDAY -> "Weekend";
};

// Switch expression with yield (for blocks)
int numLetters = switch (day) {
    case MONDAY, FRIDAY, SUNDAY -> 6;
    case TUESDAY -> 7;
    default -> {
        String label = day.toString();
        yield label.length(); // yield returns a value from a block
    }
};

// Pattern matching for switch (Java 21+)
Object obj = "Hello";
String result = switch (obj) {
    case Integer i -> "Number: " + i;
    case String s && s.length() > 5 -> "Long string: " + s;
    case String s -> "Short string: " + s;
    case null -> "Null value";
    default -> "Unknown";
};

// Enum switch with exhaustive check
enum Color { RED, GREEN, BLUE }
String hex = switch (color) {
    case RED -> "#FF0000";
    case GREEN -> "#00FF00";
    case BLUE -> "#0000FF";
};

// Multiple per case (comma-separated)
int httpStatus = switch (code) {
    case 200, 201 -> 2;
    case 400, 404 -> 4;
    case 500 -> 5;
    default -> 0;
};

