Sealed Classes (Java 17+):
// Sealed class with permits clause
public sealed class Shape permits Circle, Rectangle, Triangle { }

// Permitted subclass must be final
public final class Circle extends Shape {
    double radius;
    Circle(double radius) { this.radius = radius; }
}

// Permitted subclass can be sealed itself
public sealed class Rectangle extends Shape permits Square {
    double width, height;
    Rectangle(double w, double h) { this.width = w; this.height = h; }
}

public final class Square extends Rectangle {
    Square(double side) { super(side, side); }
}

// Permitted subclass can be non-sealed (open for extension)
public non-sealed class Triangle extends Shape {
    double base, height;
    Triangle(double b, double h) { this.base = b; this.height = h; }
}

// Sealed interface
public sealed interface Expression
    permits Constant, Add, Multiply { }
public record Constant(int value) implements Expression { }
public record Add(Expression left, Expression right) implements Expression { }
public record Multiply(Expression left, Expression right) implements Expression { }

// Exhaustive switch (Java 21+)
Shape shape = new Circle(5);
double area = switch (shape) {
    case Circle c -> Math.PI * c.radius * c.radius;
    case Rectangle r -> r.width * r.height;
    case Triangle t -> (t.base * t.height) / 2;
    // no default needed — all cases covered
};
System.out.println("Area: " + area);

Composition over Inheritance:
// Inheritance — tightly coupled
class Animal {
    void eat() { System.out.println("Eating"); }
}
class Dog extends Animal {
    void bark() { System.out.println("Barking"); }
}
// Problems: Dog cannot extend something else, changes to Animal affect Dog

// Composition — flexible and decoupled
interface Eatable {
    void eat();
}

interface Barkable {
    void bark();
}

class DogBehavior implements Eatable, Barkable {
    @Override public void eat() { System.out.println("Eating"); }
    @Override public void bark() { System.out.println("Barking"); }
}

class Dog {
    private final Eatable eatable;
    private final Barkable barkable;

    Dog(Eatable eatable, Barkable barkable) {
        this.eatable = eatable;
        this.barkable = barkable;
    }

    void eat() { eatable.eat(); }        // delegation
    void bark() { barkable.bark(); }     // delegation
    void sleep() { System.out.println("Sleeping"); } // own behavior
}

Dog dog = new Dog(new DogBehavior(), new DogBehavior());
dog.eat();
dog.bark();

// Benefits:
// - Swap behavior at runtime: new Dog(new RoboticEat(), new DigitalBark())
// - Test with mocks: new Dog(mock(Eatable.class), mock(Barkable.class))
// - No fragile base class issues

