Advanced Collectors (groupingBy / partit:
import java.util.stream.*;
import java.util.*;
import static java.util.stream.Collectors.*;

// Simple grouping
List<String> names = List.of("Alice", "Bob", "Charlie", "David", "Eve");
Map<Integer, List<String>> byLength = names.stream()
    .collect(groupingBy(String::length));
System.out.println(byLength); // {3=[Bob, Eve], 5=[Alice, David], 7=[Charlie]}

// Grouping with downstream collector
Map<Integer, Long> countByLength = names.stream()
    .collect(groupingBy(String::length, counting()));
System.out.println(countByLength); // {3=2, 5=2, 7=1}

// Grouping with mapping (transform values)
Map<Integer, List<String>> upperByLength = names.stream()
    .collect(groupingBy(String::length, mapping(String::toUpperCase, toList())));
System.out.println(upperByLength); // {3=[BOB, EVE], 5=[ALICE, DAVID], 7=[CHARLIE]}

// Partitioning — split into two groups
List<Integer> numbers = List.of(1, 2, 3, 4, 5, 6);
Map<Boolean, List<Integer>> evenOdd = numbers.stream()
    .collect(partitioningBy(n -> n % 2 == 0));
System.out.println(evenOdd); // {false=[1, 3, 5], true=[2, 4, 6]}

// Partitioning with downstream
Map<Boolean, Long> countEvenOdd = numbers.stream()
    .collect(partitioningBy(n -> n % 2 == 0, counting()));
System.out.println(countEvenOdd); // {false=3, true=3}

// teeing() to compute multiple aggregations (Java 12+)
record Stats(long count, int sum) {}
Stats stats = numbers.stream()
    .collect(teeing(
        counting(),
        summingInt(n -> n),
        Stats::new
    ));
System.out.println(stats); // Stats[count=6, sum=21]

