import java.util.*;

// ArrayList — fast random access, bulk operations
List<String> arrayList = new ArrayList<>();
arrayList.add("A");
arrayList.add("B");
arrayList.add("C");
String elem = arrayList.get(1); // O(1) — fast
arrayList.add(1, "X");          // O(n) — shifts elements
arrayList.remove(0);            // O(n) — shifts elements

// LinkedList — fast end operations, implements Deque
List<String> linkedList = new LinkedList<>();
linkedList.add("A");
linkedList.add("B");
String first = ((LinkedList<String>) linkedList).getFirst(); // O(1)
String last = ((LinkedList<String>) linkedList).getLast();   // O(1)

// LinkedList as Deque
Deque<String> deque = new LinkedList<>();
deque.addFirst("First");
deque.addLast("Last");
deque.removeFirst();
deque.removeLast();

// Performance comparison
int size = 100_000;

// ArrayList: slow prepend (shifts all elements)
List<Integer> al = new ArrayList<>();
long start = System.nanoTime();
for (int i = 0; i < 1000; i++) al.addFirst(i);
long alTime = System.nanoTime() - start;

// LinkedList: fast prepend
List<Integer> ll = new LinkedList<>();
start = System.nanoTime();
for (int i = 0; i < 1000; i++) ll.addFirst(i);
long llTime = System.nanoTime() - start;

System.out.println("ArrayList prepend: " + alTime);
System.out.println("LinkedList prepend: " + llTime);
// LinkedList is significantly faster for prepend/append

// When to use ArrayList:
// - Mostly indexed access
// - Rare insertions/removals in middle
// - Need compact memory

// When to use LinkedList:
// - Frequent insertions/removals at ends
// - Need Deque functionality
// - Memory not a concern

