import java.util.*;

public class WildcardDemo {

    // Unbounded wildcard — accepts any type
    static void printList(List<?> list) {
        for (Object o : list) System.out.print(o + " ");
        // list.add("x"); // ❌ can't add (unknown type)
    }

    // Upper-bounded — read only (Producer)
    static double sum(List<? extends Number> list) {
        double total = 0;
        for (Number n : list) total += n.doubleValue();
        return total;
    }

    // Lower-bounded — write allowed (Consumer)
    static void addNumbers(List<? super Integer> list) {
        for (int i = 1; i <= 5; i++) list.add(i);
    }
}

List<Integer> ints = List.of(1, 2, 3);
List<Double> doubles = List.of(1.5, 2.5);

WildcardDemo.printList(ints);   // 1 2 3
WildcardDemo.printList(doubles); // 1.5 2.5

System.out.println(WildcardDemo.sum(ints));    // 6.0
System.out.println(WildcardDemo.sum(doubles)); // 4.0

List<Number> nums = new ArrayList<>();
WildcardDemo.addNumbers(nums);
System.out.println(nums); // [1, 2, 3, 4, 5]

