import java.util.concurrent.atomic.*;

// Without atomic — requires synchronization
class Counter {
    private int count;
    public synchronized void increment() { count++; }
}

// With AtomicInteger — no synchronized needed
AtomicInteger atomicCount = new AtomicInteger(0);

// Thread-safe increment
atomicCount.incrementAndGet(); // equivalent to count++

// Compare-and-set
int expected = 5;
int newValue = 10;
boolean success = atomicCount.compareAndSet(expected, newValue);

// Update with function (Java 8+)
atomicCount.updateAndGet(x -> x + 5);

// Get and set
int old = atomicCount.getAndSet(100);
System.out.println("Old: " + old + ", New: " + atomicCount.get());

// AtomicReference for objects
AtomicReference<String> config = new AtomicReference<>("default");
config.compareAndSet("default", "new-config");

// LongAdder — high-contention counter
LongAdder adder = new LongAdder();
adder.increment();
adder.add(10);
long total = adder.sum(); // may not be exact during concurrent access
long accurate = adder.sumThenReset(); // snapshot + reset

