Fork/Join Framework:
import java.util.concurrent.*;

// RecursiveTask — returns a result
class SumTask extends RecursiveTask<Long> {
    private static final int THRESHOLD = 10_000;
    private final int[] array;
    private final int start, end;

    SumTask(int[] array, int start, int end) {
        this.array = array;
        this.start = start;
        this.end = end;
    }

    @Override
    protected Long compute() {
        int length = end - start;
        if (length <= THRESHOLD) {
            // Compute directly for small tasks
            long sum = 0;
            for (int i = start; i < end; i++) sum += array[i];
            return sum;
        }

        // Split in half
        int mid = start + length / 2;
        SumTask left = new SumTask(array, start, mid);
        SumTask right = new SumTask(array, mid, end);

        left.fork();          // fork left subtask (async)
        long rightResult = right.compute(); // compute right (sync)
        long leftResult = left.join();      // wait for left result

        return leftResult + rightResult;
    }
}

// Usage
int[] data = new int[100_000];
java.util.Arrays.fill(data, 1);

ForkJoinPool pool = ForkJoinPool.commonPool();
SumTask task = new SumTask(data, 0, data.length);
long result = pool.invoke(task);
System.out.println("Sum: " + result); // 100000

// RecursiveAction — void, no return
class ArrayTransform extends RecursiveAction {
    private final int[] array;
    private final int start, end;

    ArrayTransform(int[] array, int start, int end) {
        this.array = array;
        this.start = start;
        this.end = end;
    }

    @Override
    protected void compute() {
        if (end - start <= 1000) {
            for (int i = start; i < end; i++) array[i] *= 2;
        } else {
            int mid = start + (end - start) / 2;
            invokeAll(new ArrayTransform(array, start, mid),
                      new ArrayTransform(array, mid, end));
        }
    }
}

// Custom pool size
ForkJoinPool customPool = new ForkJoinPool(4); // 4 threads
customPool.invoke(new ArrayTransform(data, 0, data.length));
customPool.shutdown();

