import java.sql.*;

// Connection string format: jdbc:postgresql://host:port/database
String url = "jdbc:postgresql://localhost:5432/mydb";
String user = "admin";
String pass = "password";

// Try-with-resources auto-closes Connection, Statement, ResultSet
try (Connection conn = DriverManager.getConnection(url, user, pass);
     PreparedStatement stmt = conn.prepareStatement(
         "INSERT INTO users (name, email) VALUES (?, ?) RETURNING id")) {

    // Set parameters (safe from SQL injection)
    stmt.setString(1, "Alice");
    stmt.setString(2, "alice@example.com");

    // Execute and get generated key
    ResultSet rs = stmt.executeQuery();
    if (rs.next()) {
        System.out.println("Inserted user ID: " + rs.getInt(1));
    }

    // Query
    try (Statement query = conn.createStatement()) {
        ResultSet results = query.executeQuery("SELECT * FROM users");
        while (results.next()) {
            System.out.println(results.getString("name") + ": " +
                               results.getString("email"));
        }
    }

    // Transaction example
    conn.setAutoCommit(false);
    try {
        // perform multiple operations
        conn.commit();
    } catch (SQLException e) {
        conn.rollback();
        throw e;
    }
}
