class UserServiceTest {

    @Mock
    private UserRepository userRepo;

    @InjectMocks
    private UserService userService;

    @Test
    void testFindUser() {
        // Given
        User mockUser = new User(1L, "Alice");
        when(userRepo.findById(1L)).thenReturn(java.util.Optional.of(mockUser));

        // When
        User result = userService.findUser(1L);

        // Then
        assertEquals("Alice", result.getName());
        verify(userRepo).findById(1L); // verify the call happened
    }

    @Test
    void testDeleteUser() {
        // Given
        doNothing().when(userRepo).deleteById(anyLong());

        // When
        userService.deleteUser(1L);

        // Then
        verify(userRepo, times(1)).deleteById(1L);
    }

    @Test
    void testSaveUserException() {
        // Given
        when(userRepo.save(any())).thenThrow(new RuntimeException("DB error"));

        // When/Then
        assertThrows(RuntimeException.class, () -> userService.saveUser(new User()));
    }
}

