// Processing with reflection
import java.lang.reflect.Method;

public class AnnotationProcessor {
    public static void process(Object obj) {
        Class<?> clazz = obj.getClass();

        // Class-level annotations
        LogExecution classAnnotation = clazz.getAnnotation(LogExecution.class);
        if (classAnnotation != null) {
            System.out.println("Class: " + classAnnotation.value());
        }

        // Method-level annotations
        for (Method method : clazz.getDeclaredMethods()) {
            LogExecution methodAnnotation = method.getAnnotation(LogExecution.class);
            if (methodAnnotation != null) {
                System.out.println("Method: " + method.getName()
                    + ", logParams: " + methodAnnotation.logParams());
            }
        }
    }
}

