Pattern Matching for Switch (Java 21+):
// Before — long if-else chains
String formatValue(Object obj) {
    if (obj instanceof Integer i) {
        return "Number: " + i;
    } else if (obj instanceof String s && s.length() > 5) {
        return "Long string: " + s;
    } else if (obj instanceof String s) {
        return "Short string: " + s;
    } else if (obj == null) {
        return "Null";
    } else {
        return "Unknown: " + obj;
    }
}

// Java 21+ — clean switch expression
String formatValue(Object obj) {
    return switch (obj) {
        case Integer i -> "Number: " + i;
        case String s && s.length() > 5 -> "Long string: " + s;
        case String s -> "Short string: " + s;
        case null -> "Null";
        default -> "Unknown: " + obj;
    };
}

// With sealed classes — exhaustive matching
sealed interface Tree permits Leaf, Node { }
record Leaf(int value) implements Tree { }
record Node(Tree left, Tree right) implements Tree { }

int sum(Tree tree) {
    return switch (tree) {
        case Leaf(int v) -> v;
        case Node(var l, var r) -> sum(l) + sum(r);
        // no default needed — all subtypes covered
    };
}

// Guarded patterns
String describe(Object obj) {
    return switch (obj) {
        case Integer i && i > 0 -> "Positive int: " + i;
        case Integer i && i == 0 -> "Zero";
        case Integer i -> "Negative int: " + i;
        case String s && !s.isEmpty() -> "Non-empty string: " + s;
        case String s -> "Empty string";
        case null -> "Null";
        default -> obj.toString();
    };
}

Foreign Function & Memory API (Java 22+):
import java.lang.foreign.*;
import java.lang.invoke.*;

// Memory API — allocate off-heap memory
Arena arena = Arena.ofConfined();
MemorySegment segment = arena.allocate(100); // 100 bytes off-heap

// Write and read values
segment.setAtIndex(ValueLayout.JAVA_INT, 0, 42);
int value = segment.getAtIndex(ValueLayout.JAVA_INT, 0);
System.out.println(value); // 42

// Structured memory layout
MemoryLayout structLayout = MemoryLayout.structLayout(
    ValueLayout.JAVA_INT.withName("id"),
    ValueLayout.JAVA_DOUBLE.withName("score")
);
var idOffset = structLayout.byteOffset(MemoryLayout.PathElement.groupElement("id"));
var scoreOffset = structLayout.byteOffset(MemoryLayout.PathElement.groupElement("score"));

MemorySegment person = arena.allocate(structLayout);
person.setAtIndex(ValueLayout.JAVA_INT, 0, 1);
person.setAtIndex(ValueLayout.JAVA_DOUBLE, 1, 95.5);

// Linker API — call native C functions
Linker linker = Linker.nativeLinker();
SymbolLookup stdlib = linker.defaultLookup();

// Find and call strlen from C standard library
MethodHandle strlen = linker.downcallHandle(
    stdlib.find("strlen").orElseThrow(),
    FunctionDescriptor.of(ValueLayout.JAVA_LONG, ValueLayout.ADDRESS)
);

MemorySegment str = arena.allocateFrom("Hello, Panama!");
try {
    long len = (long) strlen.invoke(str);
    System.out.println("Length: " + len); // 13
} catch (Throwable e) {
    System.err.println("FFM call failed: " + e);
}

// Arena types:
// - ofConfined(): single-threaded access, freed when closed
// - ofShared(): multi-threaded access
// - ofAuto(): garbage-collected (no explicit close needed)
// - global(): never freed (application lifetime)

Checked vs Unchecked Exceptions:
// Checked exception — must handle or declare
import java.io.*;

void readFile(String path) throws IOException { // declare
    FileReader reader = new FileReader(path); // IOException is checked
    // ...
}

// Caller must handle or re-declare
void processFile(String path) {
    try {
        readFile(path);
    } catch (IOException e) {
        System.err.println("File error: " + e.getMessage());
    }
}

// Unchecked exception — no handling required
int divide(int a, int b) {
    if (b == 0) throw new IllegalArgumentException("Division by zero");
    return a / b;
}

// The compiler does NOT force you to catch IllegalArgumentException
// Common unchecked exceptions:
// NullPointerException, IllegalArgumentException
// IllegalStateException, IndexOutOfBoundsException
// UnsupportedOperationException, ArithmeticException

// Best practice: checked for recoverable, unchecked for bugs
class InsufficientFundsException extends Exception { // checked
    InsufficientFundsException(String msg) { super(msg); }
}

class NegativeBalanceException extends RuntimeException { // unchecked
    NegativeBalanceException(String msg) { super(msg); }
}

