Custom Exception Hierarchy:
// Base custom exception (checked)
public class AccountException extends Exception {
    public AccountException(String message) {
        super(message);
    }
    public AccountException(String message, Throwable cause) {
        super(message, cause);
    }
}

// Specific subclasses
public class InsufficientFundsException extends AccountException {
    private final double balance;
    private final double amount;

    public InsufficientFundsException(double balance, double amount) {
        super(String.format("Insufficient funds: need %.2f, have %.2f", amount, balance));
        this.balance = balance;
        this.amount = amount;
    }

    public double getBalance() { return balance; }
    public double getShortfall() { return amount - balance; }
}

public class AccountNotFoundException extends AccountException {
    public AccountNotFoundException(String accountId) {
        super("Account not found: " + accountId);
    }
}

// Usage
void withdraw(String accountId, double amount) throws AccountException {
    Account acc = findAccount(accountId);
    if (acc == null) throw new AccountNotFoundException(accountId);
    if (acc.getBalance() < amount)
        throw new InsufficientFundsException(acc.getBalance(), amount);
    acc.withdraw(amount);
}

// Caller can catch specific or base class
try {
    withdraw("ACC-001", 500);
} catch (InsufficientFundsException e) {
    System.out.println("Need " + e.getShortfall() + " more");
} catch (AccountException e) {
    System.err.println("Account error: " + e.getMessage());
}

