java.util.function Package:
import java.util.function.*;
import java.util.*;

// Function — transform input to output
Function<String, Integer> length = String::length;
System.out.println(length.apply("Hello")); // 5

// Composing functions
Function<String, String> trim = String::trim;
Function<String, Integer> trimThenLength = trim.andThen(length);
System.out.println(trimThenLength.apply("  Hi  ")); // 2

// Consumer — perform side effect
Consumer<String> logger = msg -> System.out.println("LOG: " + msg);
logger.accept("User logged in");

// Supplier — produce values
Supplier<Double> random = Math::random;
Supplier<String> uuid = () -> UUID.randomUUID().toString();

// Predicate — test condition
Predicate<String> isEmpty = String::isEmpty;
Predicate<String> isLong = s -> s.length() > 10;
Predicate<String> emptyOrLong = isEmpty.or(isLong);
System.out.println(emptyOrLong.test(""));       // true
System.out.println(emptyOrLong.test("short"));   // false

// UnaryOperator — same type in and out
UnaryOperator<String> shout = String::toUpperCase;
System.out.println(shout.apply("hello")); // HELLO

// BinaryOperator — combine two values
BinaryOperator<Integer> max = Integer::max;
System.out.println(max.apply(10, 20)); // 20

// Primitive specializations (boxing avoidance)
IntFunction<String> intToString = String::valueOf;
ToIntFunction<String> stringToInt = Integer::parseInt;

// Practical use with streams
List<String> names = List.of("Alice", "Bob", "Charlie");
names.stream()
    .filter(Predicate.not(String::isEmpty)) // Java 11+
    .map(String::toUpperCase)
    .forEach(System.out::println);

// BiFunction
BiFunction<String, Integer, String> repeat = (s, n) -> s.repeat(n);
System.out.println(repeat.apply("Ha", 3)); // HaHaHa

