// module-info.java — root of module declaration
module com.example.myapp {
    // Required modules
    requires java.sql;
    requires org.slf4j;

    // Packages accessible to other modules
    exports com.example.myapp.api;
    exports com.example.myapp.model;

    // Open package for reflection (Hibernate, Jackson, etc.)
    opens com.example.myapp.model to org.hibernate.orm;

    // Open entire module for reflection
    // open module com.example.myapp { ... }

    // Service provider (implements an SPI)
    provides com.example.myapp.spi.Plugin
        with com.example.myapp.impl.MyPlugin;

    // Service consumer (uses an SPI)
    uses com.example.myapp.spi.Plugin;

    // Transitive dependency — available to consumers of this module
    requires transitive com.google.gson;
}

